'use strict';

// MODULES //

var words = require( './words.js' );


// MAIN //

/**
* Tests whether two 64-bit unsigned integers stored in integer-valued strided array views are equal.
*
* @param {Collection} a - first 64-bit unsigned integer strided array view containing interleaved 32-bit unsigned integer high and low order words
* @param {integer} strideA - stride length for `a`
* @param {NonNegativeInteger} offsetA - starting index for `a`
* @param {Collection} b - second 64-bit unsigned integer strided array view containing interleaved 32-bit unsigned integer high and low order words
* @param {integer} strideB - stride length for `b`
* @param {NonNegativeInteger} offsetB - starting index for `b`
* @returns {boolean} boolean indicating if both 64-bit unsigned integers are equal
*
* @example
* var Uint32Array = require( '@stdlib/array/uint32' );
*
* var a = new Uint32Array( [ 0, 5 ] );
* var b = new Uint32Array( [ 0, 5 ] );
*
* var bool = strided( a, 1, 0, b, 1, 0 );
* // returns true
*/
function strided( a, strideA, offsetA, b, strideB, offsetB ) {
	return words( a[ offsetA ], a[ offsetA+strideA ], b[ offsetB ], b[ offsetB+strideB ] ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = strided;
